-- Schema of ravi.db at tag v3.261113.2, generated by that tag's own initializers
-- (router-db getDb, signals, mailbox, calendar, cloud chat, observation plane, jobs, approvals,
-- outbound publish outbox, cloud task runs, session followups, slack inbound inbox) against a newly
-- created, isolated RAVI_STATE_DIR. Never a copy of a production database. The complete table set
-- of the tag is src/threads/fence-adoption-inventory.ts, derived from every CREATE TABLE.

CREATE TABLE agents (
      id TEXT PRIMARY KEY,
      name TEXT,
      cwd TEXT NOT NULL,
      model TEXT,
      effort TEXT,
      provider TEXT,
      model_preset_id TEXT REFERENCES runtime_model_presets(id),
      remote TEXT,
      remote_user TEXT,
      dm_scope TEXT CHECK(dm_scope IS NULL OR dm_scope IN ('main','per-peer','per-channel-peer','per-account-channel-peer')),
      system_prompt_append TEXT,
      debounce_ms INTEGER,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    , matrix_account TEXT REFERENCES matrix_accounts(username), heartbeat_enabled INTEGER DEFAULT 0, heartbeat_interval_ms INTEGER DEFAULT 1800000, heartbeat_model TEXT, heartbeat_active_start TEXT, heartbeat_active_end TEXT, heartbeat_last_run_at INTEGER, setting_sources TEXT, spec_mode INTEGER DEFAULT 0, contact_scope TEXT, allowed_sessions TEXT, agent_mode TEXT, group_debounce_ms INTEGER, defaults TEXT, heartbeat_account_id TEXT);

CREATE TABLE approval_card_scopes (
      request_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      scope TEXT NOT NULL,
      updated_at INTEGER NOT NULL,
      PRIMARY KEY (request_id, user_id)
    );

CREATE TABLE approval_request_deliveries (
      request_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      kind TEXT NOT NULL,
      chat_id TEXT NOT NULL,
      message_id TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      PRIMARY KEY (request_id, user_id)
    );

CREATE TABLE approval_requests (
      id TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      channel TEXT NOT NULL,
      account_id TEXT NOT NULL,
      chat_id TEXT NOT NULL,
      instance_id TEXT,
      thread_id TEXT,
      message_id TEXT,
      session_name TEXT,
      agent_id TEXT,
      permission TEXT,
      object_type TEXT,
      object_id TEXT,
      status TEXT NOT NULL,
      decision TEXT,
      decided_by TEXT,
      reason TEXT,
      created_at INTEGER NOT NULL,
      expires_at INTEGER NOT NULL,
      decided_at INTEGER
    , subject_kind TEXT, subject_contact_id TEXT, subject_identity_id TEXT, subject_agent_id TEXT, subject_channel TEXT, subject_raw_id TEXT, grant_json TEXT, grant_intent TEXT, grant_scope TEXT, grant_outcome TEXT);

CREATE TABLE audit_log (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      action     TEXT NOT NULL,
      entity     TEXT NOT NULL,
      entity_id  TEXT NOT NULL,
      old_value  TEXT,
      actor      TEXT NOT NULL DEFAULT 'daemon',
      ts         INTEGER NOT NULL
    );

CREATE TABLE calendar_accounts (
      id TEXT PRIMARY KEY,
      provider TEXT NOT NULL,
      display_name TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('active','paused','auth_required','disabled')),
      default_calendar_id TEXT,
      credentials_ref TEXT,
      capabilities_json TEXT,
      settings_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE calendar_calendars (
      id TEXT PRIMARY KEY,
      account_id TEXT NOT NULL REFERENCES calendar_accounts(id) ON DELETE CASCADE,
      provider_calendar_id TEXT,
      name TEXT NOT NULL,
      description TEXT,
      color TEXT,
      timezone TEXT,
      role TEXT NOT NULL CHECK(role IN ('primary','secondary','shared','resource','system','unknown')),
      status TEXT NOT NULL CHECK(status IN ('active','paused','disabled','deleted')),
      visibility TEXT NOT NULL CHECK(visibility IN ('private','shared','public','local_only')),
      owner_type TEXT NOT NULL,
      owner_id TEXT NOT NULL,
      is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)),
      last_synced_at INTEGER,
      metadata_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(account_id, name)
    );

CREATE TABLE calendar_event_attendees (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES calendar_events(id) ON DELETE CASCADE,
      kind TEXT NOT NULL CHECK(kind IN ('organizer','required','optional','resource','informational')),
      response_status TEXT NOT NULL CHECK(response_status IN ('accepted','declined','tentative','needs_action','unknown')),
      email TEXT,
      normalized_email TEXT,
      display_name TEXT,
      contact_id TEXT,
      agent_id TEXT,
      platform_identity_id TEXT,
      provider_attendee_id TEXT,
      raw_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE calendar_event_audit (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES calendar_events(id) ON DELETE CASCADE,
      event_type TEXT NOT NULL,
      actor_type TEXT NOT NULL,
      actor_id TEXT,
      payload_json TEXT,
      created_at INTEGER NOT NULL
    );

CREATE TABLE calendar_event_reminders (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES calendar_events(id) ON DELETE CASCADE,
      kind TEXT NOT NULL,
      trigger_offset_ms INTEGER,
      trigger_at INTEGER,
      status TEXT NOT NULL DEFAULT 'pending',
      metadata_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE calendar_events (
      id TEXT PRIMARY KEY,
      calendar_id TEXT NOT NULL REFERENCES calendar_calendars(id) ON DELETE CASCADE,
      account_id TEXT NOT NULL REFERENCES calendar_accounts(id) ON DELETE CASCADE,
      uid TEXT NOT NULL,
      provider_event_id TEXT,
      provider_recurring_event_id TEXT,
      ical_uid TEXT,
      series_id TEXT,
      original_start_at INTEGER,
      title TEXT NOT NULL,
      description TEXT,
      description_redaction_status TEXT NOT NULL CHECK(description_redaction_status IN ('full_local','preview_only','redacted','missing')),
      location TEXT,
      location_redaction_status TEXT NOT NULL CHECK(location_redaction_status IN ('full_local','preview_only','redacted','missing')),
      status TEXT NOT NULL CHECK(status IN ('confirmed','tentative','cancelled','draft','unknown')),
      busy_status TEXT NOT NULL CHECK(busy_status IN ('busy','free','tentative','out_of_office','unknown')),
      visibility TEXT NOT NULL CHECK(visibility IN ('default','private','public','confidential')),
      start_at INTEGER NOT NULL,
      end_at INTEGER NOT NULL,
      start_timezone TEXT,
      end_timezone TEXT,
      all_day INTEGER NOT NULL DEFAULT 0 CHECK(all_day IN (0,1)),
      recurrence_rule TEXT,
      recurrence_json TEXT,
      sequence INTEGER NOT NULL DEFAULT 1,
      etag TEXT,
      organizer_contact_id TEXT,
      organizer_agent_id TEXT,
      organizer_platform_identity_id TEXT,
      creator_contact_id TEXT,
      creator_agent_id TEXT,
      creator_platform_identity_id TEXT,
      safe_payload_json TEXT,
      provider_provenance_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      deleted_at INTEGER,
      CHECK(end_at > start_at)
    );

CREATE TABLE calendar_members (
      id TEXT PRIMARY KEY,
      calendar_id TEXT NOT NULL REFERENCES calendar_calendars(id) ON DELETE CASCADE,
      member_type TEXT NOT NULL,
      member_id TEXT NOT NULL,
      relation TEXT NOT NULL CHECK(relation IN ('owner','reader','writer','manager','free_busy')),
      expires_at INTEGER,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(calendar_id, member_type, member_id, relation)
    );

CREATE TABLE calendar_outbox (
      id TEXT PRIMARY KEY,
      account_id TEXT NOT NULL REFERENCES calendar_accounts(id) ON DELETE CASCADE,
      calendar_id TEXT NOT NULL REFERENCES calendar_calendars(id) ON DELETE CASCADE,
      event_id TEXT NOT NULL REFERENCES calendar_events(id) ON DELETE CASCADE,
      operation TEXT NOT NULL CHECK(operation IN ('create','update','cancel','delete','respond')),
      idempotency_key TEXT NOT NULL UNIQUE,
      payload_json TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('pending','leased','sending','sent','acked','failed','dead')),
      attempt_count INTEGER NOT NULL DEFAULT 0,
      next_attempt_at INTEGER NOT NULL DEFAULT 0,
      last_error_code TEXT,
      provider_result_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE calendar_sync_conflicts (
      id TEXT PRIMARY KEY,
      account_id TEXT NOT NULL REFERENCES calendar_accounts(id) ON DELETE CASCADE,
      calendar_id TEXT NOT NULL REFERENCES calendar_calendars(id) ON DELETE CASCADE,
      event_id TEXT REFERENCES calendar_events(id) ON DELETE SET NULL,
      outbox_id TEXT,
      provider TEXT NOT NULL,
      conflict_type TEXT NOT NULL,
      local_version TEXT,
      remote_version TEXT,
      status TEXT NOT NULL CHECK(status IN ('open','resolved','ignored','dead')),
      resolution TEXT,
      safe_local_snapshot_json TEXT,
      safe_remote_snapshot_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE calendar_sync_cursors (
      id TEXT PRIMARY KEY,
      account_id TEXT NOT NULL REFERENCES calendar_accounts(id) ON DELETE CASCADE,
      calendar_id TEXT REFERENCES calendar_calendars(id) ON DELETE CASCADE,
      provider TEXT NOT NULL,
      cursor_type TEXT NOT NULL,
      cursor_value TEXT,
      watermark_at INTEGER,
      status TEXT NOT NULL DEFAULT 'active',
      last_success_at INTEGER,
      last_error_code TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(account_id, calendar_id, provider, cursor_type)
    );

CREATE TABLE channel_backend_ingress_receipts (
      id TEXT PRIMARY KEY,
      channel_instance_id TEXT NOT NULL,
      idempotency_key TEXT NOT NULL,
      request_fingerprint TEXT NOT NULL,
      initial_request_id TEXT NOT NULL,
      local_actor_id TEXT NOT NULL,
      agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT,
      chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE RESTRICT,
      message_id TEXT NOT NULL REFERENCES chat_messages(id) ON DELETE RESTRICT,
      session_key TEXT NOT NULL,
      session_name TEXT NOT NULL,
      turn_id TEXT NOT NULL,
      external_json TEXT NOT NULL,
      prompt_json TEXT,
      state TEXT NOT NULL DEFAULT 'accepted'
        CHECK(state IN ('accepted', 'publishing', 'published')),
      publish_claim_id TEXT,
      publish_claim_expires_at INTEGER,
      published_at INTEGER,
      accepted_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(channel_instance_id, idempotency_key),
      UNIQUE(message_id),
      UNIQUE(turn_id)
    );

CREATE TABLE channel_backend_runtime_interrupts (
      turn_id TEXT NOT NULL
        REFERENCES channel_backend_ingress_receipts(turn_id) ON DELETE CASCADE,
      idempotency_key TEXT NOT NULL,
      request_id TEXT NOT NULL,
      state TEXT NOT NULL DEFAULT 'accepted'
        CHECK(state IN ('accepted', 'publishing', 'published')),
      publish_claim_id TEXT,
      publish_claim_expires_at INTEGER,
      published_at INTEGER,
      requested_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      PRIMARY KEY(turn_id, idempotency_key)
    );

CREATE TABLE channel_backend_runtime_state (
      trace_turn_id TEXT,
      turn_id TEXT PRIMARY KEY
        REFERENCES channel_backend_ingress_receipts(turn_id) ON DELETE CASCADE,
      state TEXT NOT NULL DEFAULT 'accepted'
        CHECK(state IN (
          'accepted',
          'running',
          'waiting_approval',
          'completed',
          'failed',
          'interrupted'
        )),
      last_sequence INTEGER NOT NULL DEFAULT 0
        CHECK(last_sequence >= 0),
      last_delta_sequence INTEGER NOT NULL DEFAULT 0
        CHECK(last_delta_sequence >= 0),
      assistant_message_id TEXT
        REFERENCES chat_messages(id) ON DELETE RESTRICT,
      runtime_generation_id TEXT,
      terminal_error_json TEXT,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE channel_outbound_publish_jobs (
        idempotency_key TEXT PRIMARY KEY,
        request_fingerprint TEXT NOT NULL,
        job_id TEXT NOT NULL,
        session_name TEXT NOT NULL,
        channel_id TEXT NOT NULL,
        status TEXT NOT NULL CHECK(status IN ('pending','published','suppressed')),
        payload_json TEXT NOT NULL,
        attempt_count INTEGER NOT NULL DEFAULT 0,
        next_attempt_at INTEGER NOT NULL DEFAULT 0,
        last_error_message TEXT,
        last_error_at INTEGER,
        published_at INTEGER,
        superseded_by TEXT,
        suppression_reason TEXT,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );

CREATE TABLE channel_outbound_publish_suppressions (
        idempotency_key TEXT PRIMARY KEY,
        request_fingerprint TEXT NOT NULL,
        job_id TEXT NOT NULL,
        session_name TEXT NOT NULL,
        channel_id TEXT NOT NULL,
        attempt_count INTEGER NOT NULL,
        published_at INTEGER,
        suppression_reason TEXT NOT NULL,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );

CREATE TABLE channel_outbound_receipts (
      idempotency_key       TEXT PRIMARY KEY,
      request_fingerprint   TEXT NOT NULL,
      job_id                TEXT NOT NULL,
      request_id            TEXT NOT NULL,
      session_name          TEXT NOT NULL,
      state                 TEXT NOT NULL CHECK(state IN ('claimed','sent','persisted','complete','suppressed')),
      provider              TEXT NOT NULL,
      delivery_message_id   TEXT,
      platform_message_id   TEXT,
      provider_timestamp    INTEGER,
      canonical_message_id  TEXT,
      claim_owner           TEXT,
      claim_expires_at      INTEGER,
      sent_at               INTEGER,
      persisted_at          INTEGER,
      trace_recorded_at     INTEGER,
      completed_at          INTEGER,
      suppression_reason    TEXT,
      resend_prohibited     INTEGER NOT NULL DEFAULT 0 CHECK(resend_prohibited IN (0,1)),
      retain_identity       INTEGER NOT NULL DEFAULT 0 CHECK(retain_identity IN (0,1)),
      last_error_phase      TEXT,
      last_error_message    TEXT,
      last_error_at         INTEGER,
      created_at            INTEGER NOT NULL,
      updated_at            INTEGER NOT NULL
    );

CREATE TABLE channels (
      name         TEXT PRIMARY KEY,
      provider     TEXT NOT NULL,
      enabled      INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
      credential_connection TEXT,
      defaults     TEXT,
      created_at   INTEGER NOT NULL,
      updated_at   INTEGER NOT NULL,
      deleted_at   INTEGER
    );

CREATE TABLE chat_messages (
      id TEXT PRIMARY KEY,
      chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
      channel TEXT NOT NULL,
      instance_id TEXT NOT NULL DEFAULT '',
      provider_message_id TEXT NOT NULL,
      client_message_id TEXT,
      raw_chat_id TEXT NOT NULL,
      raw_sender_id TEXT,
      normalized_sender_id TEXT,
      actor_type TEXT NOT NULL DEFAULT 'unknown',
      actor_id TEXT,
      contact_id TEXT,
      agent_id TEXT,
      origin_session_key TEXT,
      platform_identity_id TEXT,
      message_type TEXT,
      content_json TEXT,
      raw_provenance_json TEXT,
      revision INTEGER,
      state TEXT,
      provider_timestamp INTEGER,
      edited_at INTEGER,
      deleted_at INTEGER,
      ingested_at INTEGER NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(channel, instance_id, chat_id, provider_message_id)
    );

CREATE TABLE chat_participants (
      id TEXT PRIMARY KEY,
      chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
      platform_identity_id TEXT,
      contact_id TEXT,
      agent_id TEXT,
      raw_platform_user_id TEXT,
      normalized_platform_user_id TEXT,
      role TEXT NOT NULL DEFAULT 'unknown',
      status TEXT NOT NULL DEFAULT 'active',
      source TEXT NOT NULL DEFAULT 'unknown',
      first_seen_at INTEGER NOT NULL,
      last_seen_at INTEGER NOT NULL,
      metadata_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE chat_reading_cursor_events (
      id TEXT PRIMARY KEY,
      list_id TEXT NOT NULL REFERENCES chat_reading_lists(id) ON DELETE CASCADE,
      chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
      reader_type TEXT NOT NULL,
      reader_id TEXT NOT NULL,
      previous_message_id TEXT,
      previous_message_sort_key TEXT,
      next_message_id TEXT,
      next_message_sort_key TEXT,
      reason TEXT,
      metadata_json TEXT,
      created_at INTEGER NOT NULL
    );

CREATE TABLE chat_reading_cursors (
      id TEXT PRIMARY KEY,
      list_id TEXT NOT NULL REFERENCES chat_reading_lists(id) ON DELETE CASCADE,
      chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
      reader_type TEXT NOT NULL,
      reader_id TEXT NOT NULL,
      last_read_message_id TEXT,
      last_read_message_sort_key TEXT,
      last_read_event_id TEXT,
      last_read_event_sort_key TEXT,
      last_read_at INTEGER,
      read_reason TEXT,
      metadata_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(list_id, chat_id, reader_type, reader_id)
    );

CREATE TABLE chat_reading_list_members (
      id TEXT PRIMARY KEY,
      list_id TEXT NOT NULL REFERENCES chat_reading_lists(id) ON DELETE CASCADE,
      chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
      source TEXT NOT NULL DEFAULT 'manual',
      reason TEXT,
      priority INTEGER NOT NULL DEFAULT 0,
      metadata_json TEXT,
      added_at INTEGER NOT NULL,
      removed_at INTEGER
    );

CREATE TABLE chat_reading_lists (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT,
      owner_type TEXT NOT NULL DEFAULT 'system',
      owner_id TEXT NOT NULL DEFAULT 'ravi',
      visibility TEXT NOT NULL DEFAULT 'system',
      mode TEXT NOT NULL DEFAULT 'static',
      selector_json TEXT,
      metadata_json TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      archived_at INTEGER
    );

CREATE TABLE chats (
      id TEXT PRIMARY KEY,
      channel TEXT NOT NULL,
      instance_id TEXT NOT NULL DEFAULT '',
      platform_chat_id TEXT NOT NULL,
      normalized_chat_id TEXT NOT NULL,
      actor_id TEXT,
      agent_id TEXT,
      chat_type TEXT NOT NULL DEFAULT 'unknown',
      title TEXT,
      avatar_url TEXT,
      metadata_json TEXT,
      raw_provenance_json TEXT,
      first_seen_at INTEGER NOT NULL,
      last_seen_at INTEGER NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(channel, instance_id, normalized_chat_id)
    );

CREATE TABLE cloud_agent_task_dispatches (
        task_id TEXT PRIMARY KEY,
        attempt INTEGER NOT NULL,
        idempotency_key TEXT NOT NULL,
        state TEXT NOT NULL CHECK(state IN ('pending','started','failed','abandoned')),
        run_id TEXT,
        agent_id TEXT NOT NULL,
        session_name TEXT NOT NULL,
        project TEXT NOT NULL,
        installation_id TEXT NOT NULL,
        organization_id TEXT,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );

CREATE TABLE cloud_agent_task_runs (
        run_id TEXT PRIMARY KEY,
        task_id TEXT NOT NULL,
        agent_id TEXT NOT NULL,
        session_name TEXT,
        project TEXT NOT NULL,
        state TEXT NOT NULL CHECK(state IN ('active','delivered','acknowledged')),
        status TEXT NOT NULL,
        relayed_approvals_json TEXT NOT NULL DEFAULT '[]',
        last_error TEXT,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL,
        delivered_at INTEGER,
        acknowledged_at INTEGER
      , installation_id TEXT, organization_id TEXT);

CREATE TABLE cloud_chat_approvals (
        approval_id TEXT PRIMARY KEY,
        run_id TEXT NOT NULL,
        code TEXT NOT NULL,
        session_name TEXT,
        agent_name TEXT,
        tool TEXT NOT NULL,
        actor_user_id TEXT,
        actor_contact_id TEXT,
        actor_name TEXT,
        status TEXT NOT NULL CHECK(status IN ('pending','deciding','approved','denied','closed')),
        created_at INTEGER NOT NULL,
        decided_at INTEGER,
        card_sent_at INTEGER
      );

CREATE TABLE cloud_chat_questions (
        question_id TEXT PRIMARY KEY,
        run_id TEXT NOT NULL,
        session_name TEXT,
        actor_contact_id TEXT,
        status TEXT NOT NULL CHECK(status IN ('pending','answered')),
        created_at INTEGER NOT NULL,
        answered_at INTEGER
      );

CREATE TABLE cloud_delivery_items (
        item_id TEXT PRIMARY KEY,
        event_type TEXT NOT NULL,
        run_id TEXT NOT NULL,
        session_name TEXT,
        payload_json TEXT NOT NULL,
        state TEXT NOT NULL CHECK(state IN ('pending','done','skipped','failed')),
        attempts INTEGER NOT NULL DEFAULT 0,
        next_attempt_at INTEGER NOT NULL,
        claimed_until INTEGER,
        informed_at INTEGER,
        last_error TEXT,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );

CREATE TABLE cloud_link_requests (
      id                TEXT PRIMARY KEY,
      console_url       TEXT NOT NULL,
      installation_id   TEXT NOT NULL,
      contact_id        TEXT NOT NULL,
      display_name      TEXT,
      origin_channel    TEXT,
      origin_account_id TEXT,
      origin_chat_id    TEXT,
      origin_thread_id  TEXT,
      origin_message_id TEXT,
      dm_channel        TEXT NOT NULL,
      dm_account_id     TEXT NOT NULL,
      dm_chat_id        TEXT NOT NULL,
      status            TEXT NOT NULL DEFAULT 'pending'
                        CHECK(status IN ('pending','approved','denied','expired','cancelled','failed')),
      expires_at        INTEGER NOT NULL,
      created_at        INTEGER NOT NULL,
      updated_at        INTEGER NOT NULL,
      completed_at      INTEGER
    );

CREATE TABLE cloud_thread_runs (
        id TEXT PRIMARY KEY,
        thread_key TEXT NOT NULL,
        run_id TEXT NOT NULL,
        channel TEXT NOT NULL CHECK(channel IN ('slack','whatsapp')),
        account_id TEXT NOT NULL,
        instance_id TEXT NOT NULL,
        chat_id TEXT NOT NULL,
        thread_ts TEXT,
        session_name TEXT,
        agent_name TEXT NOT NULL,
        prompt_summary TEXT,
        actor_user_id TEXT,
        actor_contact_id TEXT,
        actor_name TEXT,
        card_message_id TEXT,
        status TEXT NOT NULL,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL,
        ended_at INTEGER
      );

CREATE TABLE console_inbox_items (
      id                 INTEGER PRIMARY KEY AUTOINCREMENT,
      console_url        TEXT NOT NULL,
      organization_id    TEXT NOT NULL,
      subscription_id    TEXT NOT NULL,
      item_id            TEXT NOT NULL,
      sequence           INTEGER NOT NULL,
      event_type         TEXT NOT NULL,
      category           TEXT NOT NULL,
      severity           TEXT NOT NULL,
      dedupe_key         TEXT NOT NULL,
      nats_subject       TEXT NOT NULL,
      nats_payload_json  TEXT NOT NULL,
      delivered_at       INTEGER,
      acked_at           INTEGER,
      replay_count       INTEGER NOT NULL DEFAULT 0,
      created_at         INTEGER NOT NULL,
      updated_at         INTEGER NOT NULL,
      UNIQUE(console_url, organization_id, item_id)
    );

CREATE TABLE console_inbox_poll_locks (
      lock_key    TEXT PRIMARY KEY,
      owner_id    TEXT NOT NULL,
      acquired_at INTEGER NOT NULL,
      expires_at  INTEGER NOT NULL
    );

CREATE TABLE console_inbox_subscriptions (
      id              TEXT PRIMARY KEY,
      console_url     TEXT NOT NULL,
      organization_id TEXT NOT NULL,
      subscription_id TEXT,
      installation_id TEXT NOT NULL,
      status          TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','errored')),
      enabled         INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
      last_generation INTEGER,
      last_sequence   INTEGER,
      last_poll_at    INTEGER,
      last_success_at INTEGER,
      last_error_code TEXT,
      last_error_at   INTEGER,
      created_at      INTEGER NOT NULL,
      updated_at      INTEGER NOT NULL,
      UNIQUE(console_url, organization_id)
    );

CREATE TABLE contact_link_states (
      contact_id          TEXT PRIMARY KEY,
      status              TEXT NOT NULL CHECK(status IN ('awaiting_dm','link_sent')),
      channel             TEXT NOT NULL,
      account_id          TEXT NOT NULL,
      agent_id            TEXT,
      display_name        TEXT,
      origin_channel      TEXT,
      origin_account_id   TEXT,
      origin_chat_id      TEXT,
      origin_thread_id    TEXT,
      origin_message_id   TEXT,
      dm_chat_id          TEXT,
      route_pattern       TEXT,
      request_id          TEXT,
      request_expires_at  INTEGER,
      created_at          INTEGER NOT NULL,
      updated_at          INTEGER NOT NULL,
      expires_at          INTEGER NOT NULL
    );

CREATE TABLE contexts (
      context_id TEXT PRIMARY KEY,
      context_key TEXT NOT NULL UNIQUE,
      kind TEXT NOT NULL DEFAULT 'runtime',
      agent_id TEXT REFERENCES agents(id) ON DELETE SET NULL,
      session_key TEXT REFERENCES sessions(session_key) ON DELETE SET NULL,
      session_name TEXT,
      source_json TEXT,
      capabilities_json TEXT NOT NULL DEFAULT '[]',
      metadata_json TEXT,
      created_at INTEGER NOT NULL,
      expires_at INTEGER,
      last_used_at INTEGER,
      revoked_at INTEGER
    );

CREATE TABLE cost_events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_key TEXT NOT NULL,
      agent_id TEXT NOT NULL,
      model TEXT NOT NULL,
      input_tokens INTEGER NOT NULL,
      output_tokens INTEGER NOT NULL,
      cache_read_tokens INTEGER DEFAULT 0,
      cache_creation_tokens INTEGER DEFAULT 0,
      input_cost_usd REAL NOT NULL,
      output_cost_usd REAL NOT NULL,
      cache_cost_usd REAL DEFAULT 0,
      total_cost_usd REAL NOT NULL,
      pricing_status TEXT NOT NULL DEFAULT 'legacy',
      pricing_source TEXT,
      pricing_source_url TEXT,
      pricing_source_version TEXT,
      pricing_fetched_at INTEGER,
      pricing_model TEXT,
      pricing_error TEXT,
      created_at INTEGER NOT NULL
    );

CREATE TABLE cron_jobs (
      id TEXT PRIMARY KEY,
      agent_id TEXT,
      name TEXT NOT NULL,
      description TEXT,
      enabled INTEGER DEFAULT 1,
      delete_after_run INTEGER DEFAULT 0,

      -- Schedule (one of these is set based on schedule_type)
      schedule_type TEXT NOT NULL,
      schedule_at INTEGER,
      schedule_every INTEGER,
      schedule_cron TEXT,
      schedule_timezone TEXT,

      -- Execution config
      session_target TEXT DEFAULT 'main',
      reply_session TEXT,
      execution_type TEXT DEFAULT 'agent',
      payload_text TEXT NOT NULL,
      shell_command TEXT,
      shell_timeout_ms INTEGER,
      shell_env_file TEXT,
      on_error TEXT,
      owner_principal TEXT,

      -- State
      next_run_at INTEGER,
      last_run_at INTEGER,
      last_status TEXT,
      last_error TEXT,
      last_duration_ms INTEGER,
      last_exit_code INTEGER,

      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    , account_id TEXT, creator_chat TEXT);

CREATE TABLE cron_runs (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL,
      session_name TEXT NOT NULL,
      admitted_at INTEGER NOT NULL,
      notification_json TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('pending', 'ok', 'error')),
      finished_at INTEGER,
      error TEXT,
      reported INTEGER NOT NULL DEFAULT 0
    );

CREATE TABLE daemon_restart_epochs (
      restart_epoch TEXT PRIMARY KEY,
