      PRIMARY KEY (agent_id, date, model)
    );

CREATE TABLE decision_deliveries (
        id TEXT PRIMARY KEY, decision_id TEXT NOT NULL REFERENCES decisions(id),
        kind TEXT NOT NULL CHECK(kind IN ('question','answer')),
